namespace NotificationsApp.Services;

public class NotificationItem
{
    public int Id { get; set; }
    public string Message { get; set; } = string.Empty;
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<NotificationItem> _all = new();
    private readonly object _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data.
        _all.AddRange(new[]
        {
            MakeNotification("Welcome to NotificationsApp!"),
            MakeNotification("Your profile was updated."),
            MakeNotification("New comment on your post.")
        });
    }

    /// <summary>Returns every notification available right now.</summary>
    public Task<List<NotificationItem>> GetAllAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_all.ToList());
        }
    }

    /// <summary>Returns only notifications newer than <paramref name="sinceId"/>.</summary>
    public Task<List<NotificationItem>> GetNewerThanAsync(int sinceId)
    {
        lock (_lock)
        {
            // Simulate a new notification ~every other poll.
            if (Random.Shared.Next(2) == 0)
            {
                _all.Add(MakeNotification($"Background event #{_nextId}"));
            }

            return Task.FromResult(_all.Where(n => n.Id > sinceId).ToList());
        }
    }

    private NotificationItem MakeNotification(string message)
    {
        var item = new NotificationItem
        {
            Id = _nextId++,
            Message = message,
            Timestamp = DateTime.UtcNow
        };
        return item;
    }
}

