@page "/notifications"
@rendermode InteractiveServer
@using NotificationsApp.Services
@inject NotificationService Svc
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    @if (Notifications is not null)
    {
        <span class="badge bg-primary rounded-pill ms-2">@Notifications.Count</span>
    }
</h1>

@if (Notifications is null)
{
    <p><em>Loading...</em></p>
}
else if (Notifications.Count == 0)
{
    <p>No notifications.</p>
}
else
{
    <ul class="list-group">
        @foreach (var n in Notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-center">
                @n.Message
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private CancellationTokenSource? _cts;

    /// <summary>
    /// Persisted across the prerender → interactive handoff so the initial
    /// load is not duplicated.
    /// </summary>
    [PersistentState]
    public List<NotificationItem>? Notifications { get; set; }

    protected override async Task OnInitializedAsync()
    {
        // ??= ensures we only hit the service when state was NOT restored
        // from the prerender payload.
        Notifications ??= await Svc.GetAllAsync();
    }

    protected override void OnAfterRender(bool firstRender)
    {
        // OnAfterRender is never called during prerender, so the polling
        // loop will only start once the page is truly interactive.
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);

                var latestId = Notifications?.Count > 0
                    ? Notifications.Max(n => n.Id)
                    : 0;

                var newer = await Svc.GetNewerThanAsync(latestId);
                if (newer.Count > 0)
                {
                    Notifications ??= new();
                    Notifications.AddRange(newer);
                    await InvokeAsync(StateHasChanged);
                }
            }
            catch (OperationCanceledException)
            {
                // Expected on dispose — exit cleanly.
                break;
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

