     private CancellationTokenSource? _cts;

     /// <summary>
     /// Persisted across the prerender → interactive handoff so the initial
     /// load is not duplicated.
     /// </summary>
     [PersistentState]
     public List<NotificationItem>? Items { get; set; }

     protected override async Task OnInitializedAsync()
     {
         // ??= ensures we only hit the service when state was NOT restored
         // from the prerender payload.
         Items ??= await Svc.GetAllAsync();
     }

     protected override void OnAfterRender(bool firstRender)
     {
         // OnAfterRender is never called during prerender, so the polling
         // loop will only start once the page is truly interactive.
         if (firstRender)
         {
             _cts = new CancellationTokenSource();
             _ = PollForItemsAsync(_cts.Token);
         }
     }

     private async Task PollForItemsAsync(CancellationToken ct)
     {
         while (!ct.IsCancellationRequested)
         {
             try
             {
                 await Task.Delay(TimeSpan.FromSeconds(5), ct);

                 var latestId = Items?.Count > 0
                     ? Items.Max(n => n.Id)
                     : 0;

                 var newer = await Svc.GetNewerThanAsync(latestId);
                 if (newer.Count > 0)
                 {
                     Items ??= new();
                     Items.AddRange(newer);
                     await InvokeAsync(StateHasChanged);
                 }
             }
             catch (OperationCanceledException)
             {
                 // Expected on dispose — exit cleanly.
                 break;
             }
         }
     }

     public void Dispose()
     {
         _cts?.Cancel();
         _cts?.Dispose();
     }
 }

